import random,itertools,time,pickle

def trial(n,d,tries):
 fs=[sum(1<<v for v in f) for f in itertools.combinations(range(n),d+1)]
 sub={f:[g for g in range(1<<n) if g&f==g] for f in fs}
 rid={f:[f^(1<<v) for v in range(n) if f>>v&1] for f in fs}
 start=time.time();best=len(fs)
 for tr in range(tries):
  remaining=fs.copy();random.shuffle(remaining);fac=[];faces={0}
  while remaining:
   possible=[]
   for f in remaining:
    rr=[r for r in rid[f] if r in faces]
    if not fac or rr and all(any(g&r==g for r in rr) for g in sub[f] if g in faces):possible.append(f)
   if not possible: break
   f=random.choice(possible);remaining.remove(f);fac.append(f);faces.update(sub[f])
  if remaining and len(fac)<best:
   best=len(fac);print('STUCK',n,d,len(fac),len(remaining),flush=True);pickle.dump((n,d,fac),open('stuck.pkl','wb'));return
  if tr%10==0: print(n,d,tr,'done',time.time()-start,flush=True)
for n in [7,8,9,10]:trial(n,3,30)

