import random,itertools,time,pickle
from functools import lru_cache

def canon(fs):
 fs=set(fs)
 return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))
@lru_cache(None)
def vd(fs):
 if len(fs)<=1:return True
 if len({f.bit_count() for f in fs})!=1:return False
 rank=fs[0].bit_count();vertices=0
 for f in fs:vertices|=f
 for v in range(vertices.bit_length()):
  b=1<<v
  if vertices&b:
   dd=canon([f&~b for f in fs]);ll=canon([f&~b for f in fs if f&b])
   if dd[0].bit_count()==rank and vd(dd) and vd(ll):return True
 return False

def trial(n,d,tries):
 fs=[sum(1<<v for v in f) for f in itertools.combinations(range(n),d+1)]
 sub={f:[g for g in range(1<<n) if g&f==g] for f in fs}
 rid={f:[f^(1<<v) for v in range(n) if f>>v&1] for f in fs}
 start=time.time()
 for tr in range(tries):
  remaining=fs.copy();random.shuffle(remaining);fac=[];faces={0}
  while remaining:
   possible=[]
   for f in remaining:
    rr=[r for r in rid[f] if r in faces]
    if not fac or rr and all(any(g&r==g for r in rr) for g in sub[f] if g in faces):possible.append(f)
   if not possible:
    print('STUCK',n,d,len(fac),flush=True);pickle.dump((n,d,fac),open('stuck.pkl','wb'));return
   def score(f):return len([r for r in rid[f] if r in faces])
   mm=min(map(score,possible));f=random.choice([f for f in possible if score(f)==mm]);remaining.remove(f);fac.append(f);faces.update(sub[f])
   sk=canon([r for ff in fac for r in rid[ff]])
   if not vd(sk):
    print('NONVD SKEL',n,d,len(fac),fac,flush=True);pickle.dump((n,d,fac),open('nonvd.pkl','wb'));return
  if tr%10==0: print(n,d,tr,'done',time.time()-start,vd.cache_info(),flush=True)
for n in [7,8,9,10]:trial(n,3,10)

