# Search for a shellable, non-extendable 3-complex with Z3.
from itertools import combinations
from z3 import *
import pickle,time
n=8;r=4
facets=[sum(1<<i for i in c) for c in combinations(range(n),r)]
M=len(facets)
faces=[sum(1<<i for i in c) for s in range(1,r) for c in combinations(range(n),s)]
t={f:Int('t'+str(f)) for f in facets+faces}
s=Solver();s.set(timeout=180000)
for f in facets:s.add(t[f]>=0,t[f]<=M)
s.add(t[facets[0]]==0)
for f in facets[1:]:s.add(t[f]>0)
# Equal active times can be broken without changing the constraints, but prevent ties explicitly.
for i,f in enumerate(facets):
 for g in facets[:i]:s.add(Or(t[f]==M,t[g]==M,t[f]!=t[g]))
for h in faces:
 inc=[t[f] for f in facets if f&h==h]
 z=inc[0]
 for v in inc[1:]:z=If(z<v,z,v)
 s.add(t[h]==z)
# All vertices are present.
for i in range(n):s.add(t[1<<i]<M)
for f in facets:
 rr=[h for h in faces if h&f==h and h.bit_count()==3]
 low=[h for h in faces if h&f==h and h.bit_count()<3]
 old=lambda h:t[h]<t[f]
 if f!=facets[0]:s.add(Implies(t[f]<M,Or([old(h) for h in rr])))
 for h in low:
  s.add(Implies(And(t[f]<M,old(h)),Or([old(g) for g in rr if g&h==h])))
 # Inactive facet must NOT be attachable to the final complex.
 bad=[]
 for h in low:
  bad.append(And(t[h]<M,*[t[g]==M for g in rr if g&h==h]))
 s.add(Implies(t[f]==M,Or(bad)))
s.add(Or([t[f]==M for f in facets]))
print('starting',n,M,len(s.assertions()),flush=True)
start=time.time();res=s.check();print(res,time.time()-start,flush=True)
if res==sat:
 model=s.model();active=sorted([f for f in facets if model[t[f]].as_long()<M],key=lambda f:model[t[f]].as_long())
 print(active,flush=True);pickle.dump((n,3,active),open('sat_stuck.pkl','wb'))

